INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Darukaa.Earth — AI Biodiversity Intelligence & Ecological Reasoning System</title>\n  <meta name="description" content="State-of-the-art AI environmental scientist connecting soil health, climate, and land-use for evidence-backed biodiversity restoration.">\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">\n  <style>\n:root {\n  /* Green & White Clean Scientific Theme */\n  --bg-app: #f4f8f5;\n  --bg-gradient: radial-gradient(circle at 15% 15%, #e8f5ed 0%, #f4f8f5 55%, #ffffff 100%);\n  --bg-card: #ffffff;\n  --bg-card-hover: #f9fdfa;\n  --bg-subtle: #f0fdf4;\n  --bg-accent-mint: #dcfce7;\n  --bg-accent-light: #ecfdf5;\n\n  --border-light: #e2ede6;\n  --border-subtle: #cbdcd1;\n  --border-emerald: #a7f3d0;\n  --border-emerald-dark: #34d399;\n\n  --text-main: #0f172a;\n  --text-dark: #1e293b;\n  --text-muted: #64748b;\n  --text-subtle: #94a3b8;\n  \n  --emerald-900: #064e3b;\n  --emerald-800: #065f46;\n  --emerald-700: #047857;\n  --emerald-600: #059669;\n  --emerald-500: #10b981;\n  --emerald-400: #34d399;\n  --emerald-100: #d1fae5;\n  --emerald-50: #ecfdf5;\n\n  --leaf-green: #22c55e;\n  --cyan-accent: #0891b2;\n  --amber-accent: #d97706;\n  --amber-light: #fef3c7;\n  --amber-border: #fde68a;\n\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 16px;\n  --radius-full: 9999px;\n\n  --shadow-sm: 0 1px 3px rgba(16, 120, 80, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02);\n  --shadow-md: 0 4px 16px rgba(16, 120, 80, 0.06), 0 1px 3px rgba(0, 0, 0, 0.03);\n  --shadow-lg: 0 10px 30px rgba(16, 120, 80, 0.08), 0 2px 6px rgba(0, 0, 0, 0.04);\n  --shadow-glow: 0 0 20px rgba(16, 185, 129, 0.25);\n\n  --font-main: \'Outfit\', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-mono: \'JetBrains Mono\', monospace;\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background: var(--bg-app);\n  background-image: var(--bg-gradient);\n  background-attachment: fixed;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  line-height: 1.55;\n  overflow-x: hidden;\n}\n\n/* App Header */\n.app-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 0.85rem 2rem;\n  background: rgba(255, 255, 255, 0.95);\n  backdrop-filter: blur(16px);\n  border-bottom: 1px solid var(--border-light);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  box-shadow: 0 2px 10px rgba(16, 120, 80, 0.03);\n}\n\n.brand-group {\n  display: flex;\n  align-items: center;\n  gap: 0.9rem;\n}\n\n.logo-orb {\n  width: 40px;\n  height: 40px;\n  border-radius: var(--radius-full);\n  background: linear-gradient(135deg, var(--emerald-600), var(--emerald-400));\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.35);\n  flex-shrink: 0;\n}\n\n.orb-core {\n  width: 18px;\n  height: 18px;\n  border-radius: var(--radius-full);\n  background: #ffffff;\n}\n\n.brand-title {\n  font-size: 1.35rem;\n  font-weight: 800;\n  letter-spacing: 0.04em;\n  color: var(--emerald-900);\n}\n\n.brand-title span {\n  color: var(--emerald-600);\n}\n\n.brand-subtitle {\n  font-size: 0.78rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.header-controls {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  flex-wrap: wrap;\n}\n\n/* Badges & Buttons */\n.badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.78rem;\n  font-weight: 600;\n  padding: 0.35rem 0.8rem;\n  border-radius: var(--radius-full);\n  border: 1px solid transparent;\n}\n\n.badge-success {\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  border-color: var(--border-emerald);\n}\n\n.badge-accent {\n  background: #e0f2fe;\n  color: #0369a1;\n  border-color: #bae6fd;\n}\n\n.status-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--emerald-600);\n  box-shadow: 0 0 6px var(--emerald-500);\n}\n\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.45rem;\n  font-family: var(--font-main);\n  font-size: 0.84rem;\n  font-weight: 600;\n  padding: 0.55rem 1.1rem;\n  border-radius: var(--radius-md);\n  border: 1px solid transparent;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n  box-sizing: border-box;\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, var(--emerald-600), var(--emerald-700));\n  color: #ffffff;\n  box-shadow: 0 3px 12px rgba(5, 150, 105, 0.25);\n}\n.btn-primary:hover {\n  background: linear-gradient(135deg, var(--emerald-500), var(--emerald-600));\n  transform: translateY(-1px);\n  box-shadow: 0 6px 18px rgba(5, 150, 105, 0.35);\n}\n\n.btn-secondary {\n  background: #ffffff;\n  color: var(--emerald-900);\n  border: 1px solid var(--border-subtle);\n  box-shadow: var(--shadow-sm);\n}\n.btn-secondary:hover {\n  background: var(--emerald-50);\n  border-color: var(--emerald-500);\n  color: var(--emerald-700);\n}\n\n.btn-outline {\n  background: #ffffff;\n  color: var(--text-dark);\n  border: 1px solid var(--border-subtle);\n}\n.btn-outline:hover {\n  background: #ffffff;\n  border-color: var(--emerald-600);\n  color: var(--emerald-700);\n}\n\n.btn-accent {\n  background: linear-gradient(135deg, var(--emerald-600), var(--emerald-800));\n  color: #ffffff;\n  box-shadow: 0 4px 14px rgba(6, 78, 59, 0.2);\n}\n.btn-accent:hover {\n  background: linear-gradient(135deg, var(--emerald-500), var(--emerald-700));\n  transform: translateY(-1px);\n  box-shadow: 0 6px 18px rgba(6, 78, 59, 0.3);\n}\n\n.btn-sm {\n  padding: 0.35rem 0.75rem;\n  font-size: 0.78rem;\n  height: 34px;\n}\n\n.btn-block {\n  width: 100%;\n  justify-content: center;\n}\n\n/* Layout */\n.main-layout {\n  display: grid;\n  grid-template-columns: 460px 1fr;\n  flex: 1;\n  gap: 1.5rem;\n  padding: 1.5rem 2rem;\n  max-width: 1750px;\n  margin: 0 auto;\n  width: 100%;\n  box-sizing: border-box;\n}\n\n@media (max-width: 1100px) {\n  .main-layout {\n    grid-template-columns: 1fr;\n    padding: 1rem;\n  }\n}\n\n/* Left Panel */\n.left-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n  min-width: 0;\n  width: 100%;\n}\n\n.scenario-bar {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-md);\n  padding: 0.75rem 1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.45rem;\n  box-shadow: var(--shadow-sm);\n  width: 100%;\n  box-sizing: border-box;\n}\n\n.scenario-label {\n  font-size: 0.72rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--emerald-800);\n  font-weight: 700;\n}\n\n.scenario-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.45rem;\n}\n\n.chip {\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  color: var(--emerald-900);\n  font-size: 0.76rem;\n  font-weight: 600;\n  font-family: var(--font-main);\n  padding: 0.35rem 0.75rem;\n  border-radius: var(--radius-full);\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.chip:hover, .chip.active {\n  background: var(--emerald-600);\n  color: #ffffff;\n  border-color: var(--emerald-600);\n  box-shadow: 0 2px 8px rgba(5, 150, 105, 0.25);\n}\n\n/* Chat Stream */\n.chat-container {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-lg);\n  display: flex;\n  flex-direction: column;\n  height: 500px;\n  overflow: hidden;\n  box-shadow: var(--shadow-md);\n  width: 100%;\n  box-sizing: border-box;\n}\n\n.chat-messages {\n  flex: 1;\n  overflow-y: auto;\n  padding: 1.25rem;\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n  background: #fafdfb;\n}\n\n.message {\n  display: flex;\n  gap: 0.75rem;\n  font-size: 0.88rem;\n}\n\n.msg-avatar {\n  width: 34px;\n  height: 34px;\n  border-radius: 50%;\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.05rem;\n  flex-shrink: 0;\n  border: 1px solid var(--border-emerald);\n}\n\n.user-msg {\n  flex-direction: row-reverse;\n}\n.user-msg .msg-avatar {\n  background: #e0f2fe;\n  border-color: #bae6fd;\n}\n.user-msg .msg-body {\n  background: #f0f9ff;\n  border: 1px solid #bae6fd;\n  color: #0369a1;\n  border-radius: var(--radius-md) 0 var(--radius-md) var(--radius-md);\n  padding: 0.75rem 1rem;\n  max-width: 85%;\n  font-weight: 500;\n  box-shadow: var(--shadow-sm);\n}\n\n.system-msg .msg-body, .assistant-msg .msg-body {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  color: var(--text-dark);\n  border-radius: 0 var(--radius-md) var(--radius-md) var(--radius-md);\n  padding: 0.9rem 1.1rem;\n  max-width: 90%;\n  box-shadow: var(--shadow-sm);\n  line-height: 1.6;\n}\n\n.hint-text {\n  font-size: 0.78rem;\n  color: var(--emerald-700);\n  margin-top: 0.5rem;\n}\n\n/* Clarification Panel */\n.clarification-panel {\n  background: var(--amber-light);\n  border: 1px solid var(--amber-border);\n  border-radius: var(--radius-md);\n  margin: 0.6rem 1rem;\n  padding: 0.85rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.clarification-header {\n  display: flex;\n  align-items: center;\n  gap: 0.45rem;\n  font-size: 0.84rem;\n  color: var(--amber-accent);\n  margin-bottom: 0.45rem;\n  font-weight: 700;\n}\n\n.clarification-question {\n  margin-bottom: 0.6rem;\n  font-size: 0.82rem;\n  color: #78350f;\n}\n\n.clarification-options {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.35rem;\n  margin-top: 0.35rem;\n}\n\n.clarification-opt-btn {\n  background: #ffffff;\n  border: 1px solid var(--amber-border);\n  color: #92400e;\n  font-size: 0.74rem;\n  font-weight: 600;\n  padding: 0.3rem 0.6rem;\n  border-radius: var(--radius-sm);\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n.clarification-opt-btn:hover {\n  background: #fef3c7;\n  border-color: #d97706;\n}\n\n/* Chat Input */\n.chat-input-area {\n  padding: 0.85rem 1rem;\n  border-top: 1px solid var(--border-light);\n  background: #ffffff;\n  box-sizing: border-box;\n}\n\n.chat-form {\n  display: flex;\n  gap: 0.6rem;\n  align-items: flex-end;\n  width: 100%;\n}\n\n.chat-form textarea {\n  flex: 1;\n  min-width: 0;\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-md);\n  padding: 0.7rem 0.85rem;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.86rem;\n  resize: none;\n  transition: border-color 0.2s ease;\n  box-sizing: border-box;\n}\n.chat-form textarea:focus {\n  outline: none;\n  background: #ffffff;\n  border-color: var(--emerald-600);\n  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.15);\n}\n\n.chat-form button {\n  flex-shrink: 0;\n  height: 58px;\n}\n\n/* Params Accordion (Aligned Perfectly) */\n.params-accordion {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-md);\n  padding: 1rem;\n  box-shadow: var(--shadow-sm);\n  width: 100%;\n  box-sizing: border-box;\n  overflow: hidden;\n}\n\n.params-summary {\n  font-size: 0.88rem;\n  font-weight: 700;\n  color: var(--emerald-900);\n  cursor: pointer;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  list-style: none;\n}\n.params-summary::-webkit-details-marker {\n  display: none;\n}\n\n.params-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 0.85rem;\n  margin-top: 1rem;\n  width: 100%;\n  min-width: 0;\n  box-sizing: border-box;\n}\n\n.param-control {\n  display: flex;\n  flex-direction: column;\n  gap: 0.35rem;\n  min-width: 0;\n  width: 100%;\n  box-sizing: border-box;\n}\n.param-control.full-width {\n  grid-column: 1 / -1;\n}\n\n.param-control label {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--text-dark);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.param-control label span {\n  color: var(--emerald-700);\n  font-weight: 700;\n}\n\n.param-control input[type="range"] {\n  accent-color: var(--emerald-600);\n  height: 6px;\n  background: #e2e8f0;\n  border-radius: 3px;\n  width: 100%;\n  box-sizing: border-box;\n  cursor: pointer;\n}\n\n.form-select {\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-sm);\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.82rem;\n  padding: 0.45rem 0.65rem;\n  width: 100%;\n  box-sizing: border-box;\n  height: 36px;\n  transition: all 0.2s ease;\n}\n.form-select:focus {\n  outline: none;\n  border-color: var(--emerald-600);\n  background: #ffffff;\n}\n\n.geo-inputs {\n  display: flex;\n  gap: 0.4rem;\n  width: 100%;\n  box-sizing: border-box;\n  align-items: center;\n}\n\n.geo-inputs input {\n  flex: 1;\n  min-width: 0;\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-sm);\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.82rem;\n  padding: 0.45rem 0.65rem;\n  height: 36px;\n  box-sizing: border-box;\n}\n.geo-inputs input:focus {\n  outline: none;\n  border-color: var(--emerald-600);\n  background: #ffffff;\n}\n\n.geo-inputs button {\n  flex-shrink: 0;\n  height: 36px;\n  padding: 0 0.85rem;\n}\n\n.geo-badge {\n  margin-top: 0.4rem;\n  font-size: 0.74rem;\n  background: var(--bg-accent-mint);\n  color: var(--emerald-900);\n  border: 1px solid var(--border-emerald);\n  padding: 0.35rem 0.6rem;\n  border-radius: var(--radius-sm);\n  font-weight: 500;\n  word-break: break-word;\n}\n\n/* Right Panel (Scientific View) */\n.right-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n  min-width: 0;\n}\n\n.view-tabs {\n  display: flex;\n  gap: 0.5rem;\n  border-bottom: 2px solid var(--border-light);\n  padding-bottom: 0.5rem;\n  overflow-x: auto;\n}\n\n.tab-btn {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  color: var(--text-muted);\n  font-family: var(--font-main);\n  font-size: 0.84rem;\n  font-weight: 600;\n  padding: 0.55rem 1rem;\n  border-radius: var(--radius-md);\n  cursor: pointer;\n  white-space: nowrap;\n  transition: all 0.2s ease;\n  box-shadow: var(--shadow-sm);\n}\n\n.tab-btn:hover {\n  color: var(--emerald-800);\n  background: var(--bg-subtle);\n  border-color: var(--border-emerald);\n}\n\n.tab-btn.active {\n  background: var(--emerald-600);\n  color: #ffffff;\n  border-color: var(--emerald-600);\n  box-shadow: 0 4px 12px rgba(5, 150, 105, 0.25);\n}\n\n.tab-pane {\n  display: none;\n  flex-direction: column;\n  gap: 1.25rem;\n  min-width: 0;\n}\n.tab-pane.active {\n  display: flex;\n}\n\n/* Cards */\n.card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-lg);\n  padding: 1.4rem;\n  box-shadow: var(--shadow-md);\n  box-sizing: border-box;\n  width: 100%;\n}\n\n.diagnosis-card {\n  border-left: 5px solid var(--emerald-600);\n}\n\n.card-header {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  margin-bottom: 1rem;\n  flex-wrap: wrap;\n}\n\n.card-header h3 {\n  font-size: 1.15rem;\n  font-weight: 800;\n  color: var(--emerald-900);\n  flex: 1;\n  min-width: 200px;\n}\n\n.diagnosis-lead {\n  font-size: 0.95rem;\n  color: var(--text-dark);\n  line-height: 1.65;\n}\n\n.geo-details-box {\n  margin-top: 0.9rem;\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  border-left: 4px solid var(--emerald-600);\n  padding: 0.75rem 1rem;\n  font-size: 0.84rem;\n  color: var(--emerald-900);\n  border-radius: 0 var(--radius-md) var(--radius-md) 0;\n}\n\n.interaction-list {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  font-size: 0.88rem;\n  color: var(--text-dark);\n}\n\n.interaction-list li {\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  border-left: 4px solid var(--emerald-600);\n  padding: 0.75rem 1rem;\n  border-radius: 0 var(--radius-md) var(--radius-md) 0;\n  line-height: 1.55;\n}\n\n/* Preview Grid */\n.metrics-preview-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));\n  gap: 1rem;\n  width: 100%;\n}\n\n.metric-stat-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-top: 3px solid var(--emerald-600);\n  border-radius: var(--radius-md);\n  padding: 1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.35rem;\n  box-shadow: var(--shadow-sm);\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n  box-sizing: border-box;\n}\n.metric-stat-card:hover {\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-md);\n}\n\n.metric-stat-title {\n  font-size: 0.74rem;\n  color: var(--text-muted);\n  text-transform: uppercase;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n}\n\n.metric-stat-val {\n  font-size: 1.35rem;\n  font-weight: 800;\n  color: var(--emerald-700);\n  font-family: var(--font-mono);\n}\n\n.metric-stat-sub {\n  font-size: 0.76rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n/* Causal Flow Graph */\n.causal-chain-flow {\n  display: flex;\n  flex-direction: column;\n  gap: 1.1rem;\n  margin-top: 0.85rem;\n}\n\n.causal-node-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-left: 4px solid var(--emerald-600);\n  border-radius: var(--radius-md);\n  padding: 1.1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  position: relative;\n  box-shadow: var(--shadow-sm);\n}\n\n.causal-node-card::after {\n  content: "↓";\n  position: absolute;\n  bottom: -20px;\n  left: 50%;\n  transform: translateX(-50%);\n  color: var(--emerald-600);\n  font-size: 1.1rem;\n  font-weight: bold;\n}\n.causal-node-card:last-child::after {\n  display: none;\n}\n\n.causal-node-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.causal-input-badge {\n  background: var(--amber-light);\n  color: #92400e;\n  border: 1px solid var(--amber-border);\n  padding: 0.25rem 0.6rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.76rem;\n  font-weight: 700;\n}\n\n.causal-bio-badge {\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  border: 1px solid var(--border-emerald);\n  padding: 0.25rem 0.6rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.76rem;\n  font-weight: 700;\n}\n\n.causal-body-text {\n  font-size: 0.86rem;\n  color: var(--text-main);\n  line-height: 1.5;\n}\n\n.causal-mech {\n  border-left: 3px solid var(--emerald-500);\n  background: var(--bg-subtle);\n  padding: 0.5rem 0.8rem;\n  font-size: 0.82rem;\n  color: var(--emerald-900);\n  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;\n}\n\n/* Interventions List */\n.interventions-list {\n  display: flex;\n  flex-direction: column;\n  gap: 1.1rem;\n}\n\n.intervention-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-left: 5px solid var(--emerald-600);\n  border-radius: var(--radius-md);\n  padding: 1.25rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.intervention-title-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.intervention-title {\n  font-size: 1.05rem;\n  font-weight: 800;\n  color: var(--emerald-900);\n}\n\n.intervention-cat {\n  font-size: 0.74rem;\n  font-weight: 700;\n  background: #f1f5f9;\n  color: var(--text-dark);\n  padding: 0.25rem 0.6rem;\n  border-radius: var(--radius-full);\n  border: 1px solid #e2e8f0;\n}\n\n.intervention-block {\n  font-size: 0.86rem;\n  line-height: 1.6;\n  color: var(--text-dark);\n}\n.intervention-block strong {\n  color: var(--emerald-800);\n}\n\n.metric-pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin-top: 0.35rem;\n}\n\n.metric-pill {\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  color: var(--emerald-800);\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 0.25rem 0.55rem;\n  border-radius: var(--radius-sm);\n  font-family: var(--font-mono);\n}\n\n/* Projections Table */\n.table-responsive {\n  overflow-x: auto;\n  width: 100%;\n}\n\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.84rem;\n  text-align: left;\n}\n\n.data-table th {\n  background: #f8fafc;\n  color: var(--emerald-900);\n  padding: 0.75rem 0.9rem;\n  border-bottom: 2px solid var(--border-light);\n  font-weight: 700;\n}\n\n.data-table td {\n  padding: 0.8rem 0.9rem;\n  border-bottom: 1px solid var(--border-light);\n  color: var(--text-dark);\n}\n\n.data-table tbody tr:hover {\n  background: var(--bg-subtle);\n}\n\n.empty-cell, .empty-state {\n  text-align: center;\n  color: var(--text-muted);\n  padding: 2rem;\n  font-style: italic;\n}\n\n/* Citations Cards */\n.citations-list {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.citation-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-md);\n  padding: 1.1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.45rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.citation-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.citation-id {\n  font-size: 0.74rem;\n  font-family: var(--font-mono);\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  border: 1px solid var(--border-emerald);\n  padding: 0.2rem 0.5rem;\n  border-radius: var(--radius-sm);\n  font-weight: 700;\n}\n\n.citation-title {\n  font-size: 0.94rem;\n  font-weight: 700;\n  color: var(--emerald-900);\n}\n\n.citation-meta {\n  font-size: 0.78rem;\n  color: var(--text-muted);\n}\n\n.citation-finding {\n  font-size: 0.84rem;\n  color: var(--text-dark);\n  background: var(--bg-subtle);\n  border-left: 3px solid var(--emerald-500);\n  padding: 0.65rem 0.85rem;\n  border-radius: var(--radius-sm);\n  margin-top: 0.3rem;\n  line-height: 1.55;\n}\n\n.citation-link {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--emerald-700);\n  text-decoration: none;\n  align-self: flex-start;\n  margin-top: 0.3rem;\n}\n.citation-link:hover {\n  text-decoration: underline;\n  color: var(--emerald-900);\n}\n\n/* Modal */\n.modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(15, 23, 42, 0.45);\n  backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 200;\n}\n\n.modal-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-lg);\n  width: 90%;\n  max-width: 800px;\n  max-height: 85vh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  box-shadow: var(--shadow-lg);\n}\n\n.modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 1.1rem 1.4rem;\n  border-bottom: 1px solid var(--border-light);\n  background: #f8fafc;\n}\n.modal-header h3 {\n  font-size: 1.15rem;\n  font-weight: 800;\n  color: var(--emerald-900);\n}\n\n.modal-close {\n  background: transparent;\n  border: none;\n  font-size: 1.6rem;\n  color: var(--text-muted);\n  cursor: pointer;\n}\n.modal-close:hover {\n  color: var(--text-main);\n}\n\n.modal-body {\n  padding: 1.4rem;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 1.1rem;\n}\n\n.search-box {\n  display: flex;\n  gap: 0.6rem;\n}\n\n.search-box input {\n  flex: 1;\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-md);\n  padding: 0.65rem 0.9rem;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.88rem;\n}\n.search-box input:focus {\n  outline: none;\n  border-color: var(--emerald-600);\n  background: #ffffff;\n}\n\n.modal-results {\n  display: flex;\n  flex-direction: column;\n  gap: 0.85rem;\n}\n\n.hidden {\n  display: none !important;\n}\n\n</style>\n</head>\n<body>\n  <!-- Header Bar -->\n  <header class="app-header">\n    <div class="brand-group">\n      <div class="logo-orb">\n        <span class="orb-core"></span>\n      </div>\n      <div>\n        <h1 class="brand-title">DARUKAA<span>.EARTH</span></h1>\n        <p class="brand-subtitle">AI Biodiversity Intelligence & Ecological Reasoning Engine</p>\n      </div>\n    </div>\n\n    <div class="header-controls">\n      <div class="badge badge-success">\n        <span class="status-dot"></span> 16+ Curated Meta-Analyses Indexed\n      </div>\n      <div class="badge badge-accent">\n        <span class="icon">🌐</span> Multi-Metric Causal AI\n      </div>\n      <button id="searchKnowledgeBtn" class="btn btn-secondary">\n        <span class="icon">🔍</span> Search Literature\n      </button>\n      <button id="resetSessionBtn" class="btn btn-outline" title="Start new session">\n        <span class="icon">🔄</span> New Session\n      </button>\n    </div>\n  </header>\n\n  <!-- Main Container -->\n  <main class="main-layout">\n    <!-- Left Column: Conversational AI & Parameter Workbench -->\n    <section class="left-panel">\n      <!-- Benchmark Scenario Bar -->\n      <div class="scenario-bar">\n        <span class="scenario-label">Benchmark Scenarios:</span>\n        <div class="scenario-chips" id="scenarioChips">\n          <!-- Populated dynamically -->\n          <button class="chip" data-scenario="semi-arid-wheat-monoculture">🌾 Semi-Arid Wheat (0.3% SOC)</button>\n          <button class="chip" data-scenario="degraded-tropical-pasture">🐄 Tropical Pasture (pH 4.9)</button>\n          <button class="chip" data-scenario="riparian-agricultural-runoff">🌊 Riparian Farm Runoff</button>\n          <button class="chip" data-scenario="salinized-alkaline-cotton">🏜️ Salinized Cotton (pH 8.7)</button>\n        </div>\n      </div>\n\n      <!-- Chat Stream Window -->\n      <div class="chat-container">\n        <div class="chat-messages" id="chatMessages">\n          <div class="message system-msg">\n            <div class="msg-avatar">🌱</div>\n            <div class="msg-body">\n              <strong>Darukaa.Earth Environmental Scientist initialized.</strong>\n              <p>I analyze ecosystems across multiple biophysical variables: <strong>Soil health (pH, SOC, mycorrhizae)</strong>, <strong>Climate & Hydrology (rainfall, drought vulnerability)</strong>, and <strong>Land Use (monoculture, tillage, agroforestry)</strong> to generate evidence-backed, quantifiable biodiversity restoration plans grounded in FAO, IPCC, and IPBES literature.</p>\n              <p class="hint-text">💡 <em>Try asking: "Biodiversity is declining on my land" or pick a benchmark scenario above.</em></p>\n            </div>\n          </div>\n        </div>\n\n        <!-- Clarification Box (Dynamic) -->\n        <div id="clarificationBox" class="clarification-panel hidden">\n          <div class="clarification-header">\n            <span class="icon">⚠️</span>\n            <strong>Scientific Calibration Needed (Missing Variables Detected)</strong>\n          </div>\n          <div id="clarificationContent" class="clarification-content">\n            <!-- Dynamic questions -->\n          </div>\n        </div>\n\n        <!-- Input Box -->\n        <div class="chat-input-area">\n          <form id="chatForm" class="chat-form">\n            <textarea id="userInput" placeholder="Describe your land, soil conditions, climate, or biodiversity challenge..." rows="2" required></textarea>\n            <button type="submit" id="sendBtn" class="btn btn-primary">\n              <span>Reason</span>\n              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>\n            </button>\n          </form>\n        </div>\n      </div>\n\n      <!-- Structured Parameter Workbench (Collapsible) -->\n      <details class="params-accordion" open>\n        <summary class="params-summary">\n          <span>🛠️ Structured Parameter Workbench (Optional Fine-Tuning)</span>\n          <span class="accordion-arrow">▼</span>\n        </summary>\n        <div class="params-grid">\n          <div class="param-control">\n            <label for="socInput">Soil Organic Carbon (SOC %): <span id="socVal">0.3%</span></label>\n            <input type="range" id="socInput" min="0.1" max="5.0" step="0.1" value="0.3">\n          </div>\n          <div class="param-control">\n            <label for="phInput">Soil pH: <span id="phVal">7.8</span></label>\n            <input type="range" id="phInput" min="4.0" max="9.5" step="0.1" value="7.8">\n          </div>\n          <div class="param-control">\n            <label for="rainInput">Annual Rainfall (mm): <span id="rainVal">380 mm</span></label>\n            <input type="range" id="rainInput" min="150" max="2500" step="25" value="380">\n          </div>\n          <div class="param-control">\n            <label for="landUseSelect">Land Use Type:</label>\n            <select id="landUseSelect" class="form-select">\n              <option value="monoculture_wheat">Monoculture Wheat / Grain</option>\n              <option value="continuous_grazing_pasture">Compacted Pasture / Grazing</option>\n              <option value="intensive_rice_wheat_rotation">Intensive Rice-Wheat / Alluvial</option>\n              <option value="irrigated_cotton_monoculture">Irrigated Cotton / Row Crop</option>\n              <option value="degraded_fallow">Degraded Fallow / Orchard</option>\n            </select>\n          </div>\n          <div class="param-control">\n            <label for="geoInput">Geo-Coordinates (Lat, Lon):</label>\n            <div class="geo-inputs">\n              <input type="number" id="latInput" placeholder="Lat (e.g. 23.26)" step="0.0001">\n              <input type="number" id="lonInput" placeholder="Lon (e.g. 77.41)" step="0.0001">\n              <button type="button" id="geoLookupBtn" class="btn btn-sm btn-outline">Resolve</button>\n            </div>\n            <div id="geoResolvedBadge" class="geo-badge hidden"></div>\n          </div>\n          <div class="param-control full-width">\n            <button type="button" id="applyParamsBtn" class="btn btn-accent btn-block">\n              ⚡ Execute Structured Causal Analysis\n            </button>\n          </div>\n        </div>\n      </details>\n    </section>\n\n    <!-- Right Column: Deep Scientific Reasoning & Visual Analytics -->\n    <section class="right-panel">\n      <!-- Tabs for Scientific Views -->\n      <div class="view-tabs">\n        <button class="tab-btn active" data-tab="tab-overview">📊 Multi-Metric Intelligence</button>\n        <button class="tab-btn" data-tab="tab-causal">🧬 Causal Reasoning Graph</button>\n        <button class="tab-btn" data-tab="tab-interventions">🛠️ Evidence-Backed Interventions</button>\n        <button class="tab-btn" data-tab="tab-projections">📈 Quantified Projections</button>\n        <button class="tab-btn" data-tab="tab-citations">📚 Evidence Citations</button>\n      </div>\n\n      <!-- Tab Content Area -->\n      <div class="tab-content" id="tabContent">\n        <!-- Overview Tab -->\n        <div id="tab-overview" class="tab-pane active">\n          <!-- Executive Diagnosis Card -->\n          <div class="card diagnosis-card">\n            <div class="card-header">\n              <span class="icon">🔬</span>\n              <h3>Ecological Diagnosis & Systemic Bottlenecks</h3>\n              <span id="confidenceTag" class="badge badge-accent">94.2% Confidence</span>\n            </div>\n            <p id="diagnosisText" class="diagnosis-lead">\n              Awaiting ecosystem input parameters. Provide text query on the left or select a benchmark scenario to run multi-variable causal diagnosis.\n            </p>\n            <div id="geoDetailsBox" class="geo-details-box hidden"></div>\n          </div>\n\n          <!-- Multi-Variable Interaction Highlights -->\n          <div class="card">\n            <div class="card-header">\n              <span class="icon">🔄</span>\n              <h3>Multi-Variable Biophysical Coupling (Soil ↔ Climate ↔ Biodiversity)</h3>\n            </div>\n            <ul id="interactionList" class="interaction-list">\n              <li><em>Submit a query to inspect interconnected multi-variable relationships.</em></li>\n            </ul>\n          </div>\n\n          <!-- Quick Metrics Preview Grid -->\n          <div class="metrics-preview-grid" id="metricsPreviewGrid">\n            <!-- Populated dynamically -->\n          </div>\n        </div>\n\n        <!-- Causal Graph Tab -->\n        <div id="tab-causal" class="tab-pane">\n          <div class="card">\n            <div class="card-header">\n              <span class="icon">🧬</span>\n              <h3>Mechanistic Causal Chain Flow (Inputs → Mechanisms → Biodiversity Impact)</h3>\n            </div>\n            <p class="text-muted">Demonstrating non-obvious biophysical connections between 3+ simultaneous environmental variables:</p>\n            <div id="causalChainContainer" class="causal-chain-flow">\n              <!-- Rendered causal nodes -->\n              <div class="empty-state">Run an analysis to generate causal chain graph.</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Interventions Tab -->\n        <div id="tab-interventions" class="tab-pane">\n          <div class="card">\n            <div class="card-header">\n              <span class="icon">🛠️</span>\n              <h3>Actionable Scientific Interventions</h3>\n            </div>\n            <div id="interventionsContainer" class="interventions-list">\n              <!-- Rendered intervention cards -->\n              <div class="empty-state">No active interventions yet.</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Projections Tab -->\n        <div id="tab-projections" class="tab-pane">\n          <div class="card">\n            <div class="card-header">\n              <span class="icon">📈</span>\n              <h3>Quantified Multi-Horizon Improvement Projections</h3>\n            </div>\n            <div class="table-responsive">\n              <table class="data-table" id="projectionsTable">\n                <thead>\n                  <tr>\n                    <th>Metric Indicator</th>\n                    <th>Category</th>\n                    <th>Baseline</th>\n                    <th>Short-Term (0-1 yr)</th>\n                    <th>Medium-Term (2-4 yrs)</th>\n                    <th>Long-Term (5-10 yrs)</th>\n                    <th>Scientific Basis</th>\n                  </tr>\n                </thead>\n                <tbody id="projectionsTbody">\n                  <tr><td colspan="7" class="empty-cell">Execute analysis to see quantitative projections.</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n\n        <!-- Citations Tab -->\n        <div id="tab-citations" class="tab-pane">\n          <div class="card">\n            <div class="card-header">\n              <span class="icon">📚</span>\n              <h3>Peer-Reviewed Scientific Literature & Institutional Evidence Base</h3>\n            </div>\n            <div id="citationsContainer" class="citations-list">\n              <!-- Rendered citation cards -->\n              <div class="empty-state">No citations loaded.</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- Literature Search Modal -->\n  <div id="knowledgeModal" class="modal-overlay hidden">\n    <div class="modal-card">\n      <div class="modal-header">\n        <h3>🔍 Scientific Literature Knowledge Base Search</h3>\n        <button id="closeModalBtn" class="modal-close">&times;</button>\n      </div>\n      <div class="modal-body">\n        <div class="search-box">\n          <input type="text" id="modalSearchInput" placeholder="Search by keyword, author, mechanism (e.g. biochar, mycorrhizae, semi-arid, FAO, IPCC)...">\n          <button id="modalSearchBtn" class="btn btn-primary">Search</button>\n        </div>\n        <div id="modalSearchResults" class="modal-results">\n          <!-- Populated dynamically -->\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <script>\n// Darukaa.Earth AI Biodiversity Intelligence Frontend Client\n\nlet currentSessionId = "session_" + Math.random().toString(36).substring(2, 9);\nlet benchmarkScenarios = [];\n\ndocument.addEventListener("DOMContentLoaded", async () => {\n  initEventListeners();\n  await loadBenchmarkScenarios();\n  setupTabNavigation();\n  setupParameterSync();\n});\n\nfunction initEventListeners() {\n  // Chat form submit\n  const chatForm = document.getElementById("chatForm");\n  chatForm.addEventListener("submit", handleChatSubmit);\n\n  // Apply parameters button\n  document.getElementById("applyParamsBtn").addEventListener("click", handleStructuredSubmit);\n\n  // Geo lookup button\n  document.getElementById("geoLookupBtn").addEventListener("click", handleGeoLookup);\n\n  // Reset session\n  document.getElementById("resetSessionBtn").addEventListener("click", resetSession);\n\n  // Search Knowledge Modal\n  const modal = document.getElementById("knowledgeModal");\n  document.getElementById("searchKnowledgeBtn").addEventListener("click", () => {\n    modal.classList.remove("hidden");\n    searchLiterature("agroforestry soil organic carbon");\n  });\n  document.getElementById("closeModalBtn").addEventListener("click", () => modal.classList.add("hidden"));\n  document.getElementById("modalSearchBtn").addEventListener("click", () => {\n    const q = document.getElementById("modalSearchInput").value;\n    if (q) searchLiterature(q);\n  });\n}\n\nfunction setupTabNavigation() {\n  const tabBtns = document.querySelectorAll(".tab-btn");\n  tabBtns.forEach(btn => {\n    btn.addEventListener("click", () => {\n      tabBtns.forEach(b => b.classList.remove("active"));\n      document.querySelectorAll(".tab-pane").forEach(p => p.classList.remove("active"));\n      \n      btn.classList.add("active");\n      const targetTab = btn.getAttribute("data-tab");\n      const pane = document.getElementById(targetTab);\n      if (pane) pane.classList.add("active");\n    });\n  });\n}\n\nfunction setupParameterSync() {\n  const socInput = document.getElementById("socInput");\n  const socVal = document.getElementById("socVal");\n  socInput.addEventListener("input", (e) => socVal.textContent = `${e.target.value}%`);\n\n  const phInput = document.getElementById("phInput");\n  const phVal = document.getElementById("phVal");\n  phInput.addEventListener("input", (e) => phVal.textContent = e.target.value);\n\n  const rainInput = document.getElementById("rainInput");\n  const rainVal = document.getElementById("rainVal");\n  rainInput.addEventListener("input", (e) => rainVal.textContent = `${e.target.value} mm`);\n}\n\nasync function loadBenchmarkScenarios() {\n  try {\n    const res = await fetch("/api/scenarios");\n    if (res.ok) {\n      benchmarkScenarios = await res.json();\n      bindScenarioChips();\n    }\n  } catch (err) {\n    console.error("Failed to load scenarios:", err);\n  }\n}\n\nfunction bindScenarioChips() {\n  const chips = document.querySelectorAll(".chip");\n  chips.forEach(chip => {\n    chip.addEventListener("click", () => {\n      chips.forEach(c => c.classList.remove("active"));\n      chip.classList.add("active");\n      const scenarioId = chip.getAttribute("data-scenario");\n      const scenario = benchmarkScenarios.find(s => s.id === scenarioId);\n      if (scenario) {\n        // Populate inputs\n        document.getElementById("userInput").value = scenario.user_query;\n        if (scenario.soil_organic_carbon !== undefined) {\n          document.getElementById("socInput").value = scenario.soil_organic_carbon;\n          document.getElementById("socVal").textContent = `${scenario.soil_organic_carbon}%`;\n        }\n        if (scenario.soil_ph !== undefined) {\n          document.getElementById("phInput").value = scenario.soil_ph;\n          document.getElementById("phVal").textContent = scenario.soil_ph;\n        }\n        if (scenario.annual_rainfall_mm !== undefined) {\n          document.getElementById("rainInput").value = scenario.annual_rainfall_mm;\n          document.getElementById("rainVal").textContent = `${scenario.annual_rainfall_mm} mm`;\n        }\n        if (scenario.land_use) {\n          document.getElementById("landUseSelect").value = scenario.land_use;\n        }\n        if (scenario.coordinates) {\n          document.getElementById("latInput").value = scenario.coordinates.lat;\n          document.getElementById("lonInput").value = scenario.coordinates.lon;\n        }\n\n        // Auto trigger reasoning\n        handleChatSubmit(new Event("submit"));\n      }\n    });\n  });\n}\n\nasync function handleChatSubmit(e) {\n  if (e && e.preventDefault) e.preventDefault();\n  const inputEl = document.getElementById("userInput");\n  const message = inputEl.value.trim();\n  if (!message) return;\n\n  // Append user message to chat UI\n  appendChatMessage("user", message);\n  inputEl.value = "";\n\n  // Prepare structured context from sliders\n  const structuredContext = {\n    soil_organic_carbon: parseFloat(document.getElementById("socInput").value),\n    soil_ph: parseFloat(document.getElementById("phInput").value),\n    annual_rainfall_mm: parseFloat(document.getElementById("rainInput").value),\n    land_use: document.getElementById("landUseSelect").value\n  };\n\n  const lat = parseFloat(document.getElementById("latInput").value);\n  const lon = parseFloat(document.getElementById("lonInput").value);\n  if (!isNaN(lat) && !isNaN(lon)) {\n    structuredContext.coordinates = { lat, lon };\n  }\n\n  // Show loading indicator\n  const loadingMsgId = appendChatMessage("assistant", "🔬 <em>Analyzing multi-variable causal interactions & querying scientific literature...</em>");\n\n  try {\n    const response = await fetch("/api/chat", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({\n        session_id: currentSessionId,\n        message: message,\n        structured_context: structuredContext\n      })\n    });\n\n    if (!response.ok) {\n      throw new Error(`Server returned status ${response.status}`);\n    }\n\n    const data = await response.json();\n    removeChatMessage(loadingMsgId);\n    \n    // Render assistant markdown summary in chat\n    appendChatMessage("assistant", formatChatSummary(data));\n\n    // Render deep scientific dashboard\n    renderScientificDashboard(data);\n\n    // Handle clarification prompt if needed\n    handleClarificationDisplay(data);\n\n  } catch (err) {\n    removeChatMessage(loadingMsgId);\n    appendChatMessage("assistant", `<span style="color: var(--rose-400)">Error processing request: ${err.message}</span>`);\n  }\n}\n\nasync function handleStructuredSubmit() {\n  const structuredContext = {\n    soil_organic_carbon: parseFloat(document.getElementById("socInput").value),\n    soil_ph: parseFloat(document.getElementById("phInput").value),\n    annual_rainfall_mm: parseFloat(document.getElementById("rainInput").value),\n    land_use: document.getElementById("landUseSelect").value\n  };\n\n  const lat = parseFloat(document.getElementById("latInput").value);\n  const lon = parseFloat(document.getElementById("lonInput").value);\n  if (!isNaN(lat) && !isNaN(lon)) {\n    structuredContext.coordinates = { lat, lon };\n  }\n\n  appendChatMessage("user", `⚡ Executing direct multi-metric analysis for: SOC=${structuredContext.soil_organic_carbon}%, pH=${structuredContext.soil_ph}, Rainfall=${structuredContext.annual_rainfall_mm}mm, LandUse=${structuredContext.land_use}`);\n\n  try {\n    const response = await fetch("/api/analyze", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify(structuredContext)\n    });\n\n    if (response.ok) {\n      const data = await response.json();\n      appendChatMessage("assistant", formatChatSummary(data));\n      renderScientificDashboard(data);\n      handleClarificationDisplay(data);\n    }\n  } catch (err) {\n    console.error("Analysis failed:", err);\n  }\n}\n\nasync function handleGeoLookup() {\n  const lat = parseFloat(document.getElementById("latInput").value);\n  const lon = parseFloat(document.getElementById("lonInput").value);\n  const badge = document.getElementById("geoResolvedBadge");\n\n  if (isNaN(lat) || isNaN(lon)) {\n    alert("Please enter both valid Latitude and Longitude");\n    return;\n  }\n\n  try {\n    const res = await fetch("/api/geo/lookup", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({ lat, lon })\n    });\n    if (res.ok) {\n      const geo = await res.json();\n      badge.innerHTML = `<strong>Zone:</strong> ${geo.koppen_classification} | <strong>Biome:</strong> ${geo.biome}`;\n      badge.classList.remove("hidden");\n      if (geo.estimated_baseline_rainfall_mm) {\n        document.getElementById("rainInput").value = geo.estimated_baseline_rainfall_mm;\n        document.getElementById("rainVal").textContent = `${geo.estimated_baseline_rainfall_mm} mm`;\n      }\n    }\n  } catch (err) {\n    console.error("Geo lookup error:", err);\n  }\n}\n\nfunction handleClarificationDisplay(data) {\n  const box = document.getElementById("clarificationBox");\n  const content = document.getElementById("clarificationContent");\n\n  if (data.is_clarification_needed && data.clarification_questions.length > 0) {\n    box.classList.remove("hidden");\n    content.innerHTML = data.clarification_questions.map(q => `\n      <div class="clarification-question">\n        <div><strong>${q.question}</strong></div>\n        <div style="font-size: 0.73rem; color: var(--text-muted); margin-bottom: 0.2rem;">${q.importance}</div>\n        <div class="clarification-options">\n          ${(q.suggested_options || []).map(opt => `\n            <button class="clarification-opt-btn" onclick="applyClarificationOption(\'${opt}\')">${opt}</button>\n          `).join(\'\')}\n        </div>\n      </div>\n    `).join(\'\');\n  } else {\n    box.classList.add("hidden");\n    content.innerHTML = "";\n  }\n}\n\nwindow.applyClarificationOption = function(optText) {\n  const input = document.getElementById("userInput");\n  input.value = `Regarding parameters: ${optText}`;\n  handleChatSubmit(new Event("submit"));\n};\n\nfunction renderScientificDashboard(data) {\n  // 1. Diagnosis\n  document.getElementById("diagnosisText").textContent = data.ecological_diagnosis;\n  if (data.scientific_confidence_summary && data.scientific_confidence_summary.overall_scientific_confidence) {\n    document.getElementById("confidenceTag").textContent = data.scientific_confidence_summary.overall_scientific_confidence;\n  }\n\n  // Geo Details\n  const geoBox = document.getElementById("geoDetailsBox");\n  if (data.geo_context_resolved) {\n    const g = data.geo_context_resolved;\n    geoBox.classList.remove("hidden");\n    geoBox.innerHTML = `\n      <strong>Resolved Climate Zone:</strong> <code>${g.koppen_classification || \'N/A\'}</code> | <strong>Biome:</strong> <code>${g.biome || \'N/A\'}</code><br>\n      <strong>Dominant Soil:</strong> ${g.dominant_soil_order || \'N/A\'} | <strong>Key Vulnerability:</strong> ${(g.primary_vulnerabilities || []).join(\', \')}\n    `;\n  } else {\n    geoBox.classList.add("hidden");\n  }\n\n  // 2. Interactions list\n  const interactionList = document.getElementById("interactionList");\n  if (data.multi_variable_interactions && data.multi_variable_interactions.length > 0) {\n    interactionList.innerHTML = data.multi_variable_interactions.map(item => `<li>${item}</li>`).join(\'\');\n  }\n\n  // 3. Quick metrics preview grid\n  const previewGrid = document.getElementById("metricsPreviewGrid");\n  if (data.projected_metrics && data.projected_metrics.length > 0) {\n    previewGrid.innerHTML = data.projected_metrics.slice(0, 4).map(m => `\n      <div class="metric-stat-card">\n        <span class="metric-stat-title">${m.display_name}</span>\n        <span class="metric-stat-val">${m.medium_term_change}</span>\n        <span class="metric-stat-sub">Baseline: ${m.baseline_estimate} → 3yr target</span>\n      </div>\n    `).join(\'\');\n  }\n\n  // 4. Causal chain flow\n  const causalContainer = document.getElementById("causalChainContainer");\n  if (data.causal_chains && data.causal_chains.length > 0) {\n    causalContainer.innerHTML = data.causal_chains.map(node => `\n      <div class="causal-node-card">\n        <div class="causal-node-header">\n          <span class="causal-input-badge">Input: ${node.input_variable}</span>\n          <span class="causal-bio-badge">Target: ${node.impacted_biodiversity_indicator}</span>\n        </div>\n        <div class="causal-body-text"><strong>Direct Mechanism:</strong> ${node.direct_mechanism}</div>\n        <div class="causal-mech"><strong>Downstream Ecological Impact:</strong> ${node.downstream_impact}</div>\n        <div style="font-size: 0.74rem; color: var(--text-muted);"><strong>Scientific Rationale:</strong> ${node.scientific_rationale}</div>\n      </div>\n    `).join(\'\');\n  }\n\n  // 5. Interventions list\n  const interventionsContainer = document.getElementById("interventionsContainer");\n  if (data.interventions && data.interventions.length > 0) {\n    interventionsContainer.innerHTML = data.interventions.map((item, idx) => `\n      <div class="intervention-card">\n        <div class="intervention-title-row">\n          <div class="intervention-title">${idx + 1}. ${item.title}</div>\n          <span class="intervention-cat">${item.category}</span>\n        </div>\n        <div class="intervention-block"><strong>What to do:</strong> ${item.what_to_do}</div>\n        <div class="intervention-block"><strong>Why it works (Biophysical Mechanism):</strong> ${item.why_it_works}</div>\n        <div class="metric-pills">\n          ${item.impacted_metrics.map(m => `<span class="metric-pill">✓ ${m}</span>`).join(\'\')}\n        </div>\n        <div class="intervention-block" style="font-size: 0.75rem; color: var(--text-secondary); margin-top: 0.3rem;">\n          <strong>Time Horizon:</strong> <code>${item.time_horizon}</code> | <strong>Risk Mitigation:</strong> ${item.risks_and_mitigations}\n        </div>\n        <div style="font-size: 0.75rem; color: var(--emerald-900); font-weight: 600; margin-top: 0.3rem;">\n          <strong>Evidence Basis:</strong> ${item.confidence_rating}\n        </div>\n      </div>\n    `).join(\'\');\n  }\n\n  // 6. Projections Table\n  const tbody = document.getElementById("projectionsTbody");\n  if (data.projected_metrics && data.projected_metrics.length > 0) {\n    tbody.innerHTML = data.projected_metrics.map(m => `\n      <tr>\n        <td><strong>${m.display_name}</strong></td>\n        <td><span class="badge badge-success">${m.category}</span></td>\n        <td><code>${m.baseline_estimate}</code></td>\n        <td style="color: #0284c7; font-weight: 700;">${m.short_term_change}</td>\n        <td style="color: var(--emerald-700); font-weight: 700;">${m.medium_term_change}</td>\n        <td style="color: #4f46e5; font-weight: 700;">${m.long_term_change}</td>\n        <td style="font-size: 0.76rem; color: var(--text-dark);">${m.scientific_basis}</td>\n      </tr>\n    `).join(\'\');\n  }\n\n  // 7. Citations list\n  const citationsContainer = document.getElementById("citationsContainer");\n  if (data.citations && data.citations.length > 0) {\n    citationsContainer.innerHTML = data.citations.map(c => `\n      <div class="citation-card">\n        <div class="citation-header">\n          <span class="citation-id">${c.id}</span>\n          <span class="badge badge-success">Relevance: ${Math.round(c.relevance_score * 100)}%</span>\n        </div>\n        <div class="citation-title">${c.title} (${c.year})</div>\n        <div class="citation-meta">${c.authors} — <em>${c.publisher}</em></div>\n        <div class="citation-finding">${c.relevant_finding}</div>\n        <a href="${c.doi_or_url}" target="_blank" rel="noopener noreferrer" class="citation-link">\n          🔗 Open DOI / Institutional Report Reference &rarr;\n        </a>\n      </div>\n    `).join(\'\');\n  }\n}\n\nasync function searchLiterature(query) {\n  const container = document.getElementById("modalSearchResults");\n  container.innerHTML = "<em>Searching 16+ indexed peer-reviewed studies...</em>";\n  try {\n    const res = await fetch(`/api/knowledge/search?q=${encodeURIComponent(query)}&top_k=5`);\n    if (res.ok) {\n      const data = await res.json();\n      if (data.results.length === 0) {\n        container.innerHTML = "No matching research studies found for that query.";\n        return;\n      }\n      container.innerHTML = data.results.map(c => `\n        <div class="citation-card">\n          <div class="citation-header">\n            <span class="citation-id">${c.id}</span>\n            <span class="badge badge-accent">Match Score: ${c.relevance_score}</span>\n          </div>\n          <div class="citation-title">${c.title} (${c.year})</div>\n          <div class="citation-meta">${c.authors} — ${c.publisher}</div>\n          <div class="citation-finding">${c.relevant_finding}</div>\n          <a href="${c.doi_or_url}" target="_blank" rel="noopener noreferrer" class="citation-link">\n            Open Publication &rarr;\n          </a>\n        </div>\n      `).join(\'\');\n    }\n  } catch (err) {\n    container.innerHTML = `Error searching literature: ${err.message}`;\n  }\n}\n\nfunction formatChatSummary(data) {\n  let html = `<p><strong>${data.ecological_diagnosis}</strong></p>`;\n  if (data.interventions && data.interventions.length > 0) {\n    html += `<p style="margin-top:0.4rem;"><strong>Recommended Scientific Interventions:</strong></p><ul style="padding-left:1.2rem; margin-top:0.2rem;">`;\n    data.interventions.forEach(item => {\n      html += `<li><strong>${item.title}:</strong> ${item.impacted_metrics.slice(0, 2).join(\', \')}</li>`;\n    });\n    html += `</ul>`;\n  }\n  html += `<p style="font-size:0.8rem; color:var(--emerald-800); font-weight: 600; margin-top:0.4rem;">📊 <em>Full multi-metric causal graphs, quantitative 10-year projections, and FAO/IPCC citations populated in the right scientific workbench.</em></p>`;\n  return html;\n}\n\nfunction appendChatMessage(role, content) {\n  const container = document.getElementById("chatMessages");\n  const msgId = "msg_" + Math.random().toString(36).substring(2, 9);\n  const div = document.createElement("div");\n  div.className = `message ${role}-msg`;\n  div.id = msgId;\n\n  const avatar = role === "user" ? "🧑\u200d🌾" : (role === "assistant" ? "🌱" : "ℹ️");\n  div.innerHTML = `\n    <div class="msg-avatar">${avatar}</div>\n    <div class="msg-body">${content}</div>\n  `;\n  container.appendChild(div);\n  container.scrollTop = container.scrollHeight;\n  return msgId;\n}\n\nfunction removeChatMessage(id) {\n  const el = document.getElementById(id);\n  if (el) el.remove();\n}\n\nfunction resetSession() {\n  currentSessionId = "session_" + Math.random().toString(36).substring(2, 9);\n  const container = document.getElementById("chatMessages");\n  container.innerHTML = `\n    <div class="message system-msg">\n      <div class="msg-avatar">🌱</div>\n      <div class="msg-body">\n        <strong>New session initialized (${currentSessionId}).</strong>\n        <p>Conversational memory reset. Provide ecosystem variables to run fresh multi-metric diagnosis.</p>\n      </div>\n    </div>\n  `;\n  document.getElementById("clarificationBox").classList.add("hidden");\n}\n\n</script>\n</body>\n</html>\n'
STYLE_CSS = ':root {\n  /* Green & White Clean Scientific Theme */\n  --bg-app: #f4f8f5;\n  --bg-gradient: radial-gradient(circle at 15% 15%, #e8f5ed 0%, #f4f8f5 55%, #ffffff 100%);\n  --bg-card: #ffffff;\n  --bg-card-hover: #f9fdfa;\n  --bg-subtle: #f0fdf4;\n  --bg-accent-mint: #dcfce7;\n  --bg-accent-light: #ecfdf5;\n\n  --border-light: #e2ede6;\n  --border-subtle: #cbdcd1;\n  --border-emerald: #a7f3d0;\n  --border-emerald-dark: #34d399;\n\n  --text-main: #0f172a;\n  --text-dark: #1e293b;\n  --text-muted: #64748b;\n  --text-subtle: #94a3b8;\n  \n  --emerald-900: #064e3b;\n  --emerald-800: #065f46;\n  --emerald-700: #047857;\n  --emerald-600: #059669;\n  --emerald-500: #10b981;\n  --emerald-400: #34d399;\n  --emerald-100: #d1fae5;\n  --emerald-50: #ecfdf5;\n\n  --leaf-green: #22c55e;\n  --cyan-accent: #0891b2;\n  --amber-accent: #d97706;\n  --amber-light: #fef3c7;\n  --amber-border: #fde68a;\n\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 16px;\n  --radius-full: 9999px;\n\n  --shadow-sm: 0 1px 3px rgba(16, 120, 80, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02);\n  --shadow-md: 0 4px 16px rgba(16, 120, 80, 0.06), 0 1px 3px rgba(0, 0, 0, 0.03);\n  --shadow-lg: 0 10px 30px rgba(16, 120, 80, 0.08), 0 2px 6px rgba(0, 0, 0, 0.04);\n  --shadow-glow: 0 0 20px rgba(16, 185, 129, 0.25);\n\n  --font-main: \'Outfit\', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-mono: \'JetBrains Mono\', monospace;\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background: var(--bg-app);\n  background-image: var(--bg-gradient);\n  background-attachment: fixed;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  line-height: 1.55;\n  overflow-x: hidden;\n}\n\n/* App Header */\n.app-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 0.85rem 2rem;\n  background: rgba(255, 255, 255, 0.95);\n  backdrop-filter: blur(16px);\n  border-bottom: 1px solid var(--border-light);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  box-shadow: 0 2px 10px rgba(16, 120, 80, 0.03);\n}\n\n.brand-group {\n  display: flex;\n  align-items: center;\n  gap: 0.9rem;\n}\n\n.logo-orb {\n  width: 40px;\n  height: 40px;\n  border-radius: var(--radius-full);\n  background: linear-gradient(135deg, var(--emerald-600), var(--emerald-400));\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.35);\n  flex-shrink: 0;\n}\n\n.orb-core {\n  width: 18px;\n  height: 18px;\n  border-radius: var(--radius-full);\n  background: #ffffff;\n}\n\n.brand-title {\n  font-size: 1.35rem;\n  font-weight: 800;\n  letter-spacing: 0.04em;\n  color: var(--emerald-900);\n}\n\n.brand-title span {\n  color: var(--emerald-600);\n}\n\n.brand-subtitle {\n  font-size: 0.78rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.header-controls {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  flex-wrap: wrap;\n}\n\n/* Badges & Buttons */\n.badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.78rem;\n  font-weight: 600;\n  padding: 0.35rem 0.8rem;\n  border-radius: var(--radius-full);\n  border: 1px solid transparent;\n}\n\n.badge-success {\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  border-color: var(--border-emerald);\n}\n\n.badge-accent {\n  background: #e0f2fe;\n  color: #0369a1;\n  border-color: #bae6fd;\n}\n\n.status-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--emerald-600);\n  box-shadow: 0 0 6px var(--emerald-500);\n}\n\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.45rem;\n  font-family: var(--font-main);\n  font-size: 0.84rem;\n  font-weight: 600;\n  padding: 0.55rem 1.1rem;\n  border-radius: var(--radius-md);\n  border: 1px solid transparent;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n  box-sizing: border-box;\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, var(--emerald-600), var(--emerald-700));\n  color: #ffffff;\n  box-shadow: 0 3px 12px rgba(5, 150, 105, 0.25);\n}\n.btn-primary:hover {\n  background: linear-gradient(135deg, var(--emerald-500), var(--emerald-600));\n  transform: translateY(-1px);\n  box-shadow: 0 6px 18px rgba(5, 150, 105, 0.35);\n}\n\n.btn-secondary {\n  background: #ffffff;\n  color: var(--emerald-900);\n  border: 1px solid var(--border-subtle);\n  box-shadow: var(--shadow-sm);\n}\n.btn-secondary:hover {\n  background: var(--emerald-50);\n  border-color: var(--emerald-500);\n  color: var(--emerald-700);\n}\n\n.btn-outline {\n  background: #ffffff;\n  color: var(--text-dark);\n  border: 1px solid var(--border-subtle);\n}\n.btn-outline:hover {\n  background: #ffffff;\n  border-color: var(--emerald-600);\n  color: var(--emerald-700);\n}\n\n.btn-accent {\n  background: linear-gradient(135deg, var(--emerald-600), var(--emerald-800));\n  color: #ffffff;\n  box-shadow: 0 4px 14px rgba(6, 78, 59, 0.2);\n}\n.btn-accent:hover {\n  background: linear-gradient(135deg, var(--emerald-500), var(--emerald-700));\n  transform: translateY(-1px);\n  box-shadow: 0 6px 18px rgba(6, 78, 59, 0.3);\n}\n\n.btn-sm {\n  padding: 0.35rem 0.75rem;\n  font-size: 0.78rem;\n  height: 34px;\n}\n\n.btn-block {\n  width: 100%;\n  justify-content: center;\n}\n\n/* Layout */\n.main-layout {\n  display: grid;\n  grid-template-columns: 460px 1fr;\n  flex: 1;\n  gap: 1.5rem;\n  padding: 1.5rem 2rem;\n  max-width: 1750px;\n  margin: 0 auto;\n  width: 100%;\n  box-sizing: border-box;\n}\n\n@media (max-width: 1100px) {\n  .main-layout {\n    grid-template-columns: 1fr;\n    padding: 1rem;\n  }\n}\n\n/* Left Panel */\n.left-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n  min-width: 0;\n  width: 100%;\n}\n\n.scenario-bar {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-md);\n  padding: 0.75rem 1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.45rem;\n  box-shadow: var(--shadow-sm);\n  width: 100%;\n  box-sizing: border-box;\n}\n\n.scenario-label {\n  font-size: 0.72rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--emerald-800);\n  font-weight: 700;\n}\n\n.scenario-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.45rem;\n}\n\n.chip {\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  color: var(--emerald-900);\n  font-size: 0.76rem;\n  font-weight: 600;\n  font-family: var(--font-main);\n  padding: 0.35rem 0.75rem;\n  border-radius: var(--radius-full);\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.chip:hover, .chip.active {\n  background: var(--emerald-600);\n  color: #ffffff;\n  border-color: var(--emerald-600);\n  box-shadow: 0 2px 8px rgba(5, 150, 105, 0.25);\n}\n\n/* Chat Stream */\n.chat-container {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-lg);\n  display: flex;\n  flex-direction: column;\n  height: 500px;\n  overflow: hidden;\n  box-shadow: var(--shadow-md);\n  width: 100%;\n  box-sizing: border-box;\n}\n\n.chat-messages {\n  flex: 1;\n  overflow-y: auto;\n  padding: 1.25rem;\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n  background: #fafdfb;\n}\n\n.message {\n  display: flex;\n  gap: 0.75rem;\n  font-size: 0.88rem;\n}\n\n.msg-avatar {\n  width: 34px;\n  height: 34px;\n  border-radius: 50%;\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.05rem;\n  flex-shrink: 0;\n  border: 1px solid var(--border-emerald);\n}\n\n.user-msg {\n  flex-direction: row-reverse;\n}\n.user-msg .msg-avatar {\n  background: #e0f2fe;\n  border-color: #bae6fd;\n}\n.user-msg .msg-body {\n  background: #f0f9ff;\n  border: 1px solid #bae6fd;\n  color: #0369a1;\n  border-radius: var(--radius-md) 0 var(--radius-md) var(--radius-md);\n  padding: 0.75rem 1rem;\n  max-width: 85%;\n  font-weight: 500;\n  box-shadow: var(--shadow-sm);\n}\n\n.system-msg .msg-body, .assistant-msg .msg-body {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  color: var(--text-dark);\n  border-radius: 0 var(--radius-md) var(--radius-md) var(--radius-md);\n  padding: 0.9rem 1.1rem;\n  max-width: 90%;\n  box-shadow: var(--shadow-sm);\n  line-height: 1.6;\n}\n\n.hint-text {\n  font-size: 0.78rem;\n  color: var(--emerald-700);\n  margin-top: 0.5rem;\n}\n\n/* Clarification Panel */\n.clarification-panel {\n  background: var(--amber-light);\n  border: 1px solid var(--amber-border);\n  border-radius: var(--radius-md);\n  margin: 0.6rem 1rem;\n  padding: 0.85rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.clarification-header {\n  display: flex;\n  align-items: center;\n  gap: 0.45rem;\n  font-size: 0.84rem;\n  color: var(--amber-accent);\n  margin-bottom: 0.45rem;\n  font-weight: 700;\n}\n\n.clarification-question {\n  margin-bottom: 0.6rem;\n  font-size: 0.82rem;\n  color: #78350f;\n}\n\n.clarification-options {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.35rem;\n  margin-top: 0.35rem;\n}\n\n.clarification-opt-btn {\n  background: #ffffff;\n  border: 1px solid var(--amber-border);\n  color: #92400e;\n  font-size: 0.74rem;\n  font-weight: 600;\n  padding: 0.3rem 0.6rem;\n  border-radius: var(--radius-sm);\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n.clarification-opt-btn:hover {\n  background: #fef3c7;\n  border-color: #d97706;\n}\n\n/* Chat Input */\n.chat-input-area {\n  padding: 0.85rem 1rem;\n  border-top: 1px solid var(--border-light);\n  background: #ffffff;\n  box-sizing: border-box;\n}\n\n.chat-form {\n  display: flex;\n  gap: 0.6rem;\n  align-items: flex-end;\n  width: 100%;\n}\n\n.chat-form textarea {\n  flex: 1;\n  min-width: 0;\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-md);\n  padding: 0.7rem 0.85rem;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.86rem;\n  resize: none;\n  transition: border-color 0.2s ease;\n  box-sizing: border-box;\n}\n.chat-form textarea:focus {\n  outline: none;\n  background: #ffffff;\n  border-color: var(--emerald-600);\n  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.15);\n}\n\n.chat-form button {\n  flex-shrink: 0;\n  height: 58px;\n}\n\n/* Params Accordion (Aligned Perfectly) */\n.params-accordion {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-md);\n  padding: 1rem;\n  box-shadow: var(--shadow-sm);\n  width: 100%;\n  box-sizing: border-box;\n  overflow: hidden;\n}\n\n.params-summary {\n  font-size: 0.88rem;\n  font-weight: 700;\n  color: var(--emerald-900);\n  cursor: pointer;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  list-style: none;\n}\n.params-summary::-webkit-details-marker {\n  display: none;\n}\n\n.params-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 0.85rem;\n  margin-top: 1rem;\n  width: 100%;\n  min-width: 0;\n  box-sizing: border-box;\n}\n\n.param-control {\n  display: flex;\n  flex-direction: column;\n  gap: 0.35rem;\n  min-width: 0;\n  width: 100%;\n  box-sizing: border-box;\n}\n.param-control.full-width {\n  grid-column: 1 / -1;\n}\n\n.param-control label {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--text-dark);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.param-control label span {\n  color: var(--emerald-700);\n  font-weight: 700;\n}\n\n.param-control input[type="range"] {\n  accent-color: var(--emerald-600);\n  height: 6px;\n  background: #e2e8f0;\n  border-radius: 3px;\n  width: 100%;\n  box-sizing: border-box;\n  cursor: pointer;\n}\n\n.form-select {\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-sm);\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.82rem;\n  padding: 0.45rem 0.65rem;\n  width: 100%;\n  box-sizing: border-box;\n  height: 36px;\n  transition: all 0.2s ease;\n}\n.form-select:focus {\n  outline: none;\n  border-color: var(--emerald-600);\n  background: #ffffff;\n}\n\n.geo-inputs {\n  display: flex;\n  gap: 0.4rem;\n  width: 100%;\n  box-sizing: border-box;\n  align-items: center;\n}\n\n.geo-inputs input {\n  flex: 1;\n  min-width: 0;\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-sm);\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.82rem;\n  padding: 0.45rem 0.65rem;\n  height: 36px;\n  box-sizing: border-box;\n}\n.geo-inputs input:focus {\n  outline: none;\n  border-color: var(--emerald-600);\n  background: #ffffff;\n}\n\n.geo-inputs button {\n  flex-shrink: 0;\n  height: 36px;\n  padding: 0 0.85rem;\n}\n\n.geo-badge {\n  margin-top: 0.4rem;\n  font-size: 0.74rem;\n  background: var(--bg-accent-mint);\n  color: var(--emerald-900);\n  border: 1px solid var(--border-emerald);\n  padding: 0.35rem 0.6rem;\n  border-radius: var(--radius-sm);\n  font-weight: 500;\n  word-break: break-word;\n}\n\n/* Right Panel (Scientific View) */\n.right-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n  min-width: 0;\n}\n\n.view-tabs {\n  display: flex;\n  gap: 0.5rem;\n  border-bottom: 2px solid var(--border-light);\n  padding-bottom: 0.5rem;\n  overflow-x: auto;\n}\n\n.tab-btn {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  color: var(--text-muted);\n  font-family: var(--font-main);\n  font-size: 0.84rem;\n  font-weight: 600;\n  padding: 0.55rem 1rem;\n  border-radius: var(--radius-md);\n  cursor: pointer;\n  white-space: nowrap;\n  transition: all 0.2s ease;\n  box-shadow: var(--shadow-sm);\n}\n\n.tab-btn:hover {\n  color: var(--emerald-800);\n  background: var(--bg-subtle);\n  border-color: var(--border-emerald);\n}\n\n.tab-btn.active {\n  background: var(--emerald-600);\n  color: #ffffff;\n  border-color: var(--emerald-600);\n  box-shadow: 0 4px 12px rgba(5, 150, 105, 0.25);\n}\n\n.tab-pane {\n  display: none;\n  flex-direction: column;\n  gap: 1.25rem;\n  min-width: 0;\n}\n.tab-pane.active {\n  display: flex;\n}\n\n/* Cards */\n.card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-lg);\n  padding: 1.4rem;\n  box-shadow: var(--shadow-md);\n  box-sizing: border-box;\n  width: 100%;\n}\n\n.diagnosis-card {\n  border-left: 5px solid var(--emerald-600);\n}\n\n.card-header {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  margin-bottom: 1rem;\n  flex-wrap: wrap;\n}\n\n.card-header h3 {\n  font-size: 1.15rem;\n  font-weight: 800;\n  color: var(--emerald-900);\n  flex: 1;\n  min-width: 200px;\n}\n\n.diagnosis-lead {\n  font-size: 0.95rem;\n  color: var(--text-dark);\n  line-height: 1.65;\n}\n\n.geo-details-box {\n  margin-top: 0.9rem;\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  border-left: 4px solid var(--emerald-600);\n  padding: 0.75rem 1rem;\n  font-size: 0.84rem;\n  color: var(--emerald-900);\n  border-radius: 0 var(--radius-md) var(--radius-md) 0;\n}\n\n.interaction-list {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  font-size: 0.88rem;\n  color: var(--text-dark);\n}\n\n.interaction-list li {\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  border-left: 4px solid var(--emerald-600);\n  padding: 0.75rem 1rem;\n  border-radius: 0 var(--radius-md) var(--radius-md) 0;\n  line-height: 1.55;\n}\n\n/* Preview Grid */\n.metrics-preview-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));\n  gap: 1rem;\n  width: 100%;\n}\n\n.metric-stat-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-top: 3px solid var(--emerald-600);\n  border-radius: var(--radius-md);\n  padding: 1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.35rem;\n  box-shadow: var(--shadow-sm);\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n  box-sizing: border-box;\n}\n.metric-stat-card:hover {\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-md);\n}\n\n.metric-stat-title {\n  font-size: 0.74rem;\n  color: var(--text-muted);\n  text-transform: uppercase;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n}\n\n.metric-stat-val {\n  font-size: 1.35rem;\n  font-weight: 800;\n  color: var(--emerald-700);\n  font-family: var(--font-mono);\n}\n\n.metric-stat-sub {\n  font-size: 0.76rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n/* Causal Flow Graph */\n.causal-chain-flow {\n  display: flex;\n  flex-direction: column;\n  gap: 1.1rem;\n  margin-top: 0.85rem;\n}\n\n.causal-node-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-left: 4px solid var(--emerald-600);\n  border-radius: var(--radius-md);\n  padding: 1.1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  position: relative;\n  box-shadow: var(--shadow-sm);\n}\n\n.causal-node-card::after {\n  content: "↓";\n  position: absolute;\n  bottom: -20px;\n  left: 50%;\n  transform: translateX(-50%);\n  color: var(--emerald-600);\n  font-size: 1.1rem;\n  font-weight: bold;\n}\n.causal-node-card:last-child::after {\n  display: none;\n}\n\n.causal-node-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.causal-input-badge {\n  background: var(--amber-light);\n  color: #92400e;\n  border: 1px solid var(--amber-border);\n  padding: 0.25rem 0.6rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.76rem;\n  font-weight: 700;\n}\n\n.causal-bio-badge {\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  border: 1px solid var(--border-emerald);\n  padding: 0.25rem 0.6rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.76rem;\n  font-weight: 700;\n}\n\n.causal-body-text {\n  font-size: 0.86rem;\n  color: var(--text-main);\n  line-height: 1.5;\n}\n\n.causal-mech {\n  border-left: 3px solid var(--emerald-500);\n  background: var(--bg-subtle);\n  padding: 0.5rem 0.8rem;\n  font-size: 0.82rem;\n  color: var(--emerald-900);\n  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;\n}\n\n/* Interventions List */\n.interventions-list {\n  display: flex;\n  flex-direction: column;\n  gap: 1.1rem;\n}\n\n.intervention-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-left: 5px solid var(--emerald-600);\n  border-radius: var(--radius-md);\n  padding: 1.25rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.intervention-title-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.intervention-title {\n  font-size: 1.05rem;\n  font-weight: 800;\n  color: var(--emerald-900);\n}\n\n.intervention-cat {\n  font-size: 0.74rem;\n  font-weight: 700;\n  background: #f1f5f9;\n  color: var(--text-dark);\n  padding: 0.25rem 0.6rem;\n  border-radius: var(--radius-full);\n  border: 1px solid #e2e8f0;\n}\n\n.intervention-block {\n  font-size: 0.86rem;\n  line-height: 1.6;\n  color: var(--text-dark);\n}\n.intervention-block strong {\n  color: var(--emerald-800);\n}\n\n.metric-pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin-top: 0.35rem;\n}\n\n.metric-pill {\n  background: var(--bg-subtle);\n  border: 1px solid var(--border-emerald);\n  color: var(--emerald-800);\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 0.25rem 0.55rem;\n  border-radius: var(--radius-sm);\n  font-family: var(--font-mono);\n}\n\n/* Projections Table */\n.table-responsive {\n  overflow-x: auto;\n  width: 100%;\n}\n\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.84rem;\n  text-align: left;\n}\n\n.data-table th {\n  background: #f8fafc;\n  color: var(--emerald-900);\n  padding: 0.75rem 0.9rem;\n  border-bottom: 2px solid var(--border-light);\n  font-weight: 700;\n}\n\n.data-table td {\n  padding: 0.8rem 0.9rem;\n  border-bottom: 1px solid var(--border-light);\n  color: var(--text-dark);\n}\n\n.data-table tbody tr:hover {\n  background: var(--bg-subtle);\n}\n\n.empty-cell, .empty-state {\n  text-align: center;\n  color: var(--text-muted);\n  padding: 2rem;\n  font-style: italic;\n}\n\n/* Citations Cards */\n.citations-list {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.citation-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-md);\n  padding: 1.1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.45rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.citation-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.citation-id {\n  font-size: 0.74rem;\n  font-family: var(--font-mono);\n  background: var(--emerald-100);\n  color: var(--emerald-800);\n  border: 1px solid var(--border-emerald);\n  padding: 0.2rem 0.5rem;\n  border-radius: var(--radius-sm);\n  font-weight: 700;\n}\n\n.citation-title {\n  font-size: 0.94rem;\n  font-weight: 700;\n  color: var(--emerald-900);\n}\n\n.citation-meta {\n  font-size: 0.78rem;\n  color: var(--text-muted);\n}\n\n.citation-finding {\n  font-size: 0.84rem;\n  color: var(--text-dark);\n  background: var(--bg-subtle);\n  border-left: 3px solid var(--emerald-500);\n  padding: 0.65rem 0.85rem;\n  border-radius: var(--radius-sm);\n  margin-top: 0.3rem;\n  line-height: 1.55;\n}\n\n.citation-link {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--emerald-700);\n  text-decoration: none;\n  align-self: flex-start;\n  margin-top: 0.3rem;\n}\n.citation-link:hover {\n  text-decoration: underline;\n  color: var(--emerald-900);\n}\n\n/* Modal */\n.modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(15, 23, 42, 0.45);\n  backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 200;\n}\n\n.modal-card {\n  background: #ffffff;\n  border: 1px solid var(--border-light);\n  border-radius: var(--radius-lg);\n  width: 90%;\n  max-width: 800px;\n  max-height: 85vh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  box-shadow: var(--shadow-lg);\n}\n\n.modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 1.1rem 1.4rem;\n  border-bottom: 1px solid var(--border-light);\n  background: #f8fafc;\n}\n.modal-header h3 {\n  font-size: 1.15rem;\n  font-weight: 800;\n  color: var(--emerald-900);\n}\n\n.modal-close {\n  background: transparent;\n  border: none;\n  font-size: 1.6rem;\n  color: var(--text-muted);\n  cursor: pointer;\n}\n.modal-close:hover {\n  color: var(--text-main);\n}\n\n.modal-body {\n  padding: 1.4rem;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 1.1rem;\n}\n\n.search-box {\n  display: flex;\n  gap: 0.6rem;\n}\n\n.search-box input {\n  flex: 1;\n  background: #f8fafc;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-md);\n  padding: 0.65rem 0.9rem;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.88rem;\n}\n.search-box input:focus {\n  outline: none;\n  border-color: var(--emerald-600);\n  background: #ffffff;\n}\n\n.modal-results {\n  display: flex;\n  flex-direction: column;\n  gap: 0.85rem;\n}\n\n.hidden {\n  display: none !important;\n}\n'
APP_JS = '// Darukaa.Earth AI Biodiversity Intelligence Frontend Client\n\nlet currentSessionId = "session_" + Math.random().toString(36).substring(2, 9);\nlet benchmarkScenarios = [];\n\ndocument.addEventListener("DOMContentLoaded", async () => {\n  initEventListeners();\n  await loadBenchmarkScenarios();\n  setupTabNavigation();\n  setupParameterSync();\n});\n\nfunction initEventListeners() {\n  // Chat form submit\n  const chatForm = document.getElementById("chatForm");\n  chatForm.addEventListener("submit", handleChatSubmit);\n\n  // Apply parameters button\n  document.getElementById("applyParamsBtn").addEventListener("click", handleStructuredSubmit);\n\n  // Geo lookup button\n  document.getElementById("geoLookupBtn").addEventListener("click", handleGeoLookup);\n\n  // Reset session\n  document.getElementById("resetSessionBtn").addEventListener("click", resetSession);\n\n  // Search Knowledge Modal\n  const modal = document.getElementById("knowledgeModal");\n  document.getElementById("searchKnowledgeBtn").addEventListener("click", () => {\n    modal.classList.remove("hidden");\n    searchLiterature("agroforestry soil organic carbon");\n  });\n  document.getElementById("closeModalBtn").addEventListener("click", () => modal.classList.add("hidden"));\n  document.getElementById("modalSearchBtn").addEventListener("click", () => {\n    const q = document.getElementById("modalSearchInput").value;\n    if (q) searchLiterature(q);\n  });\n}\n\nfunction setupTabNavigation() {\n  const tabBtns = document.querySelectorAll(".tab-btn");\n  tabBtns.forEach(btn => {\n    btn.addEventListener("click", () => {\n      tabBtns.forEach(b => b.classList.remove("active"));\n      document.querySelectorAll(".tab-pane").forEach(p => p.classList.remove("active"));\n      \n      btn.classList.add("active");\n      const targetTab = btn.getAttribute("data-tab");\n      const pane = document.getElementById(targetTab);\n      if (pane) pane.classList.add("active");\n    });\n  });\n}\n\nfunction setupParameterSync() {\n  const socInput = document.getElementById("socInput");\n  const socVal = document.getElementById("socVal");\n  socInput.addEventListener("input", (e) => socVal.textContent = `${e.target.value}%`);\n\n  const phInput = document.getElementById("phInput");\n  const phVal = document.getElementById("phVal");\n  phInput.addEventListener("input", (e) => phVal.textContent = e.target.value);\n\n  const rainInput = document.getElementById("rainInput");\n  const rainVal = document.getElementById("rainVal");\n  rainInput.addEventListener("input", (e) => rainVal.textContent = `${e.target.value} mm`);\n}\n\nasync function loadBenchmarkScenarios() {\n  try {\n    const res = await fetch("/api/scenarios");\n    if (res.ok) {\n      benchmarkScenarios = await res.json();\n      bindScenarioChips();\n    }\n  } catch (err) {\n    console.error("Failed to load scenarios:", err);\n  }\n}\n\nfunction bindScenarioChips() {\n  const chips = document.querySelectorAll(".chip");\n  chips.forEach(chip => {\n    chip.addEventListener("click", () => {\n      chips.forEach(c => c.classList.remove("active"));\n      chip.classList.add("active");\n      const scenarioId = chip.getAttribute("data-scenario");\n      const scenario = benchmarkScenarios.find(s => s.id === scenarioId);\n      if (scenario) {\n        // Populate inputs\n        document.getElementById("userInput").value = scenario.user_query;\n        if (scenario.soil_organic_carbon !== undefined) {\n          document.getElementById("socInput").value = scenario.soil_organic_carbon;\n          document.getElementById("socVal").textContent = `${scenario.soil_organic_carbon}%`;\n        }\n        if (scenario.soil_ph !== undefined) {\n          document.getElementById("phInput").value = scenario.soil_ph;\n          document.getElementById("phVal").textContent = scenario.soil_ph;\n        }\n        if (scenario.annual_rainfall_mm !== undefined) {\n          document.getElementById("rainInput").value = scenario.annual_rainfall_mm;\n          document.getElementById("rainVal").textContent = `${scenario.annual_rainfall_mm} mm`;\n        }\n        if (scenario.land_use) {\n          document.getElementById("landUseSelect").value = scenario.land_use;\n        }\n        if (scenario.coordinates) {\n          document.getElementById("latInput").value = scenario.coordinates.lat;\n          document.getElementById("lonInput").value = scenario.coordinates.lon;\n        }\n\n        // Auto trigger reasoning\n        handleChatSubmit(new Event("submit"));\n      }\n    });\n  });\n}\n\nasync function handleChatSubmit(e) {\n  if (e && e.preventDefault) e.preventDefault();\n  const inputEl = document.getElementById("userInput");\n  const message = inputEl.value.trim();\n  if (!message) return;\n\n  // Append user message to chat UI\n  appendChatMessage("user", message);\n  inputEl.value = "";\n\n  // Prepare structured context from sliders\n  const structuredContext = {\n    soil_organic_carbon: parseFloat(document.getElementById("socInput").value),\n    soil_ph: parseFloat(document.getElementById("phInput").value),\n    annual_rainfall_mm: parseFloat(document.getElementById("rainInput").value),\n    land_use: document.getElementById("landUseSelect").value\n  };\n\n  const lat = parseFloat(document.getElementById("latInput").value);\n  const lon = parseFloat(document.getElementById("lonInput").value);\n  if (!isNaN(lat) && !isNaN(lon)) {\n    structuredContext.coordinates = { lat, lon };\n  }\n\n  // Show loading indicator\n  const loadingMsgId = appendChatMessage("assistant", "🔬 <em>Analyzing multi-variable causal interactions & querying scientific literature...</em>");\n\n  try {\n    const response = await fetch("/api/chat", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({\n        session_id: currentSessionId,\n        message: message,\n        structured_context: structuredContext\n      })\n    });\n\n    if (!response.ok) {\n      throw new Error(`Server returned status ${response.status}`);\n    }\n\n    const data = await response.json();\n    removeChatMessage(loadingMsgId);\n    \n    // Render assistant markdown summary in chat\n    appendChatMessage("assistant", formatChatSummary(data));\n\n    // Render deep scientific dashboard\n    renderScientificDashboard(data);\n\n    // Handle clarification prompt if needed\n    handleClarificationDisplay(data);\n\n  } catch (err) {\n    removeChatMessage(loadingMsgId);\n    appendChatMessage("assistant", `<span style="color: var(--rose-400)">Error processing request: ${err.message}</span>`);\n  }\n}\n\nasync function handleStructuredSubmit() {\n  const structuredContext = {\n    soil_organic_carbon: parseFloat(document.getElementById("socInput").value),\n    soil_ph: parseFloat(document.getElementById("phInput").value),\n    annual_rainfall_mm: parseFloat(document.getElementById("rainInput").value),\n    land_use: document.getElementById("landUseSelect").value\n  };\n\n  const lat = parseFloat(document.getElementById("latInput").value);\n  const lon = parseFloat(document.getElementById("lonInput").value);\n  if (!isNaN(lat) && !isNaN(lon)) {\n    structuredContext.coordinates = { lat, lon };\n  }\n\n  appendChatMessage("user", `⚡ Executing direct multi-metric analysis for: SOC=${structuredContext.soil_organic_carbon}%, pH=${structuredContext.soil_ph}, Rainfall=${structuredContext.annual_rainfall_mm}mm, LandUse=${structuredContext.land_use}`);\n\n  try {\n    const response = await fetch("/api/analyze", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify(structuredContext)\n    });\n\n    if (response.ok) {\n      const data = await response.json();\n      appendChatMessage("assistant", formatChatSummary(data));\n      renderScientificDashboard(data);\n      handleClarificationDisplay(data);\n    }\n  } catch (err) {\n    console.error("Analysis failed:", err);\n  }\n}\n\nasync function handleGeoLookup() {\n  const lat = parseFloat(document.getElementById("latInput").value);\n  const lon = parseFloat(document.getElementById("lonInput").value);\n  const badge = document.getElementById("geoResolvedBadge");\n\n  if (isNaN(lat) || isNaN(lon)) {\n    alert("Please enter both valid Latitude and Longitude");\n    return;\n  }\n\n  try {\n    const res = await fetch("/api/geo/lookup", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({ lat, lon })\n    });\n    if (res.ok) {\n      const geo = await res.json();\n      badge.innerHTML = `<strong>Zone:</strong> ${geo.koppen_classification} | <strong>Biome:</strong> ${geo.biome}`;\n      badge.classList.remove("hidden");\n      if (geo.estimated_baseline_rainfall_mm) {\n        document.getElementById("rainInput").value = geo.estimated_baseline_rainfall_mm;\n        document.getElementById("rainVal").textContent = `${geo.estimated_baseline_rainfall_mm} mm`;\n      }\n    }\n  } catch (err) {\n    console.error("Geo lookup error:", err);\n  }\n}\n\nfunction handleClarificationDisplay(data) {\n  const box = document.getElementById("clarificationBox");\n  const content = document.getElementById("clarificationContent");\n\n  if (data.is_clarification_needed && data.clarification_questions.length > 0) {\n    box.classList.remove("hidden");\n    content.innerHTML = data.clarification_questions.map(q => `\n      <div class="clarification-question">\n        <div><strong>${q.question}</strong></div>\n        <div style="font-size: 0.73rem; color: var(--text-muted); margin-bottom: 0.2rem;">${q.importance}</div>\n        <div class="clarification-options">\n          ${(q.suggested_options || []).map(opt => `\n            <button class="clarification-opt-btn" onclick="applyClarificationOption(\'${opt}\')">${opt}</button>\n          `).join(\'\')}\n        </div>\n      </div>\n    `).join(\'\');\n  } else {\n    box.classList.add("hidden");\n    content.innerHTML = "";\n  }\n}\n\nwindow.applyClarificationOption = function(optText) {\n  const input = document.getElementById("userInput");\n  input.value = `Regarding parameters: ${optText}`;\n  handleChatSubmit(new Event("submit"));\n};\n\nfunction renderScientificDashboard(data) {\n  // 1. Diagnosis\n  document.getElementById("diagnosisText").textContent = data.ecological_diagnosis;\n  if (data.scientific_confidence_summary && data.scientific_confidence_summary.overall_scientific_confidence) {\n    document.getElementById("confidenceTag").textContent = data.scientific_confidence_summary.overall_scientific_confidence;\n  }\n\n  // Geo Details\n  const geoBox = document.getElementById("geoDetailsBox");\n  if (data.geo_context_resolved) {\n    const g = data.geo_context_resolved;\n    geoBox.classList.remove("hidden");\n    geoBox.innerHTML = `\n      <strong>Resolved Climate Zone:</strong> <code>${g.koppen_classification || \'N/A\'}</code> | <strong>Biome:</strong> <code>${g.biome || \'N/A\'}</code><br>\n      <strong>Dominant Soil:</strong> ${g.dominant_soil_order || \'N/A\'} | <strong>Key Vulnerability:</strong> ${(g.primary_vulnerabilities || []).join(\', \')}\n    `;\n  } else {\n    geoBox.classList.add("hidden");\n  }\n\n  // 2. Interactions list\n  const interactionList = document.getElementById("interactionList");\n  if (data.multi_variable_interactions && data.multi_variable_interactions.length > 0) {\n    interactionList.innerHTML = data.multi_variable_interactions.map(item => `<li>${item}</li>`).join(\'\');\n  }\n\n  // 3. Quick metrics preview grid\n  const previewGrid = document.getElementById("metricsPreviewGrid");\n  if (data.projected_metrics && data.projected_metrics.length > 0) {\n    previewGrid.innerHTML = data.projected_metrics.slice(0, 4).map(m => `\n      <div class="metric-stat-card">\n        <span class="metric-stat-title">${m.display_name}</span>\n        <span class="metric-stat-val">${m.medium_term_change}</span>\n        <span class="metric-stat-sub">Baseline: ${m.baseline_estimate} → 3yr target</span>\n      </div>\n    `).join(\'\');\n  }\n\n  // 4. Causal chain flow\n  const causalContainer = document.getElementById("causalChainContainer");\n  if (data.causal_chains && data.causal_chains.length > 0) {\n    causalContainer.innerHTML = data.causal_chains.map(node => `\n      <div class="causal-node-card">\n        <div class="causal-node-header">\n          <span class="causal-input-badge">Input: ${node.input_variable}</span>\n          <span class="causal-bio-badge">Target: ${node.impacted_biodiversity_indicator}</span>\n        </div>\n        <div class="causal-body-text"><strong>Direct Mechanism:</strong> ${node.direct_mechanism}</div>\n        <div class="causal-mech"><strong>Downstream Ecological Impact:</strong> ${node.downstream_impact}</div>\n        <div style="font-size: 0.74rem; color: var(--text-muted);"><strong>Scientific Rationale:</strong> ${node.scientific_rationale}</div>\n      </div>\n    `).join(\'\');\n  }\n\n  // 5. Interventions list\n  const interventionsContainer = document.getElementById("interventionsContainer");\n  if (data.interventions && data.interventions.length > 0) {\n    interventionsContainer.innerHTML = data.interventions.map((item, idx) => `\n      <div class="intervention-card">\n        <div class="intervention-title-row">\n          <div class="intervention-title">${idx + 1}. ${item.title}</div>\n          <span class="intervention-cat">${item.category}</span>\n        </div>\n        <div class="intervention-block"><strong>What to do:</strong> ${item.what_to_do}</div>\n        <div class="intervention-block"><strong>Why it works (Biophysical Mechanism):</strong> ${item.why_it_works}</div>\n        <div class="metric-pills">\n          ${item.impacted_metrics.map(m => `<span class="metric-pill">✓ ${m}</span>`).join(\'\')}\n        </div>\n        <div class="intervention-block" style="font-size: 0.75rem; color: var(--text-secondary); margin-top: 0.3rem;">\n          <strong>Time Horizon:</strong> <code>${item.time_horizon}</code> | <strong>Risk Mitigation:</strong> ${item.risks_and_mitigations}\n        </div>\n        <div style="font-size: 0.75rem; color: var(--emerald-900); font-weight: 600; margin-top: 0.3rem;">\n          <strong>Evidence Basis:</strong> ${item.confidence_rating}\n        </div>\n      </div>\n    `).join(\'\');\n  }\n\n  // 6. Projections Table\n  const tbody = document.getElementById("projectionsTbody");\n  if (data.projected_metrics && data.projected_metrics.length > 0) {\n    tbody.innerHTML = data.projected_metrics.map(m => `\n      <tr>\n        <td><strong>${m.display_name}</strong></td>\n        <td><span class="badge badge-success">${m.category}</span></td>\n        <td><code>${m.baseline_estimate}</code></td>\n        <td style="color: #0284c7; font-weight: 700;">${m.short_term_change}</td>\n        <td style="color: var(--emerald-700); font-weight: 700;">${m.medium_term_change}</td>\n        <td style="color: #4f46e5; font-weight: 700;">${m.long_term_change}</td>\n        <td style="font-size: 0.76rem; color: var(--text-dark);">${m.scientific_basis}</td>\n      </tr>\n    `).join(\'\');\n  }\n\n  // 7. Citations list\n  const citationsContainer = document.getElementById("citationsContainer");\n  if (data.citations && data.citations.length > 0) {\n    citationsContainer.innerHTML = data.citations.map(c => `\n      <div class="citation-card">\n        <div class="citation-header">\n          <span class="citation-id">${c.id}</span>\n          <span class="badge badge-success">Relevance: ${Math.round(c.relevance_score * 100)}%</span>\n        </div>\n        <div class="citation-title">${c.title} (${c.year})</div>\n        <div class="citation-meta">${c.authors} — <em>${c.publisher}</em></div>\n        <div class="citation-finding">${c.relevant_finding}</div>\n        <a href="${c.doi_or_url}" target="_blank" rel="noopener noreferrer" class="citation-link">\n          🔗 Open DOI / Institutional Report Reference &rarr;\n        </a>\n      </div>\n    `).join(\'\');\n  }\n}\n\nasync function searchLiterature(query) {\n  const container = document.getElementById("modalSearchResults");\n  container.innerHTML = "<em>Searching 16+ indexed peer-reviewed studies...</em>";\n  try {\n    const res = await fetch(`/api/knowledge/search?q=${encodeURIComponent(query)}&top_k=5`);\n    if (res.ok) {\n      const data = await res.json();\n      if (data.results.length === 0) {\n        container.innerHTML = "No matching research studies found for that query.";\n        return;\n      }\n      container.innerHTML = data.results.map(c => `\n        <div class="citation-card">\n          <div class="citation-header">\n            <span class="citation-id">${c.id}</span>\n            <span class="badge badge-accent">Match Score: ${c.relevance_score}</span>\n          </div>\n          <div class="citation-title">${c.title} (${c.year})</div>\n          <div class="citation-meta">${c.authors} — ${c.publisher}</div>\n          <div class="citation-finding">${c.relevant_finding}</div>\n          <a href="${c.doi_or_url}" target="_blank" rel="noopener noreferrer" class="citation-link">\n            Open Publication &rarr;\n          </a>\n        </div>\n      `).join(\'\');\n    }\n  } catch (err) {\n    container.innerHTML = `Error searching literature: ${err.message}`;\n  }\n}\n\nfunction formatChatSummary(data) {\n  let html = `<p><strong>${data.ecological_diagnosis}</strong></p>`;\n  if (data.interventions && data.interventions.length > 0) {\n    html += `<p style="margin-top:0.4rem;"><strong>Recommended Scientific Interventions:</strong></p><ul style="padding-left:1.2rem; margin-top:0.2rem;">`;\n    data.interventions.forEach(item => {\n      html += `<li><strong>${item.title}:</strong> ${item.impacted_metrics.slice(0, 2).join(\', \')}</li>`;\n    });\n    html += `</ul>`;\n  }\n  html += `<p style="font-size:0.8rem; color:var(--emerald-800); font-weight: 600; margin-top:0.4rem;">📊 <em>Full multi-metric causal graphs, quantitative 10-year projections, and FAO/IPCC citations populated in the right scientific workbench.</em></p>`;\n  return html;\n}\n\nfunction appendChatMessage(role, content) {\n  const container = document.getElementById("chatMessages");\n  const msgId = "msg_" + Math.random().toString(36).substring(2, 9);\n  const div = document.createElement("div");\n  div.className = `message ${role}-msg`;\n  div.id = msgId;\n\n  const avatar = role === "user" ? "🧑\u200d🌾" : (role === "assistant" ? "🌱" : "ℹ️");\n  div.innerHTML = `\n    <div class="msg-avatar">${avatar}</div>\n    <div class="msg-body">${content}</div>\n  `;\n  container.appendChild(div);\n  container.scrollTop = container.scrollHeight;\n  return msgId;\n}\n\nfunction removeChatMessage(id) {\n  const el = document.getElementById(id);\n  if (el) el.remove();\n}\n\nfunction resetSession() {\n  currentSessionId = "session_" + Math.random().toString(36).substring(2, 9);\n  const container = document.getElementById("chatMessages");\n  container.innerHTML = `\n    <div class="message system-msg">\n      <div class="msg-avatar">🌱</div>\n      <div class="msg-body">\n        <strong>New session initialized (${currentSessionId}).</strong>\n        <p>Conversational memory reset. Provide ecosystem variables to run fresh multi-metric diagnosis.</p>\n      </div>\n    </div>\n  `;\n  document.getElementById("clarificationBox").classList.add("hidden");\n}\n'
